// spec: .qa/e2e/specs/nusach-switch.md
// seed: tests/seed.user1.spec.ts
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { startNearestPrayer } from '../_helpers/prayer-start';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

async function counterText(page: Page) {
  const body = await page.locator('body').innerText();
  return (body.match(/\d+ מתוך \d+/) ?? [''])[0];
}

test.describe('Смена нусаха внутри молитвы', () => {
  test('NS-02 После смены нусаха в молитве профиль не меняется #6a86f7d8 @prod-safe @mobile', async ({ page }) => {
    // 1. Открыть `/prayer/mincha_ashkenaz`; нажимать «קודם», пока не будет «1 מתוך 8».
    await page.goto('/prayer/mincha_ashkenaz');
    await expect(page.getByText(/\d+ מתוך \d+/).first()).toBeVisible();
    const prev = page.getByText('קודם', { exact: true });
    for (let i = 0; i < 15; i++) {
      if ((await counterText(page)) === '1 מתוך 8') break;
      await prev.click();
    }
    await expect(page.getByText('1 מתוך 8')).toBeVisible();

    // 2. Меню нусаха → «ספרדי» → «החלף»; убедиться, что заголовок «מנחה (ספרדי)».
    await page.getByLabel(/^בחירת נוסח/).click();
    await page.getByRole('radio', { name: 'ספרדי' }).click();
    await page.getByRole('alert').getByRole('button', { name: 'החלף' }).click();
    await expect(page.getByRole('heading', { level: 1, name: 'מנחה (ספרדי)' })).toBeVisible();

    // 3. Перейти в профиль, найти поле «נוסח תפילה».
    await page.goto('/profile');
    await expect(page.getByText('נוסח תפילה', { exact: true })).toBeVisible();
    await expect(page.locator('body')).toContainText(/נוסח תפילה\s*אשכנז(?!י)/);
    await expect(page.locator('body')).not.toContainText(/נוסח תפילה\s*ספרד/);

    // 4. Перейти на главную `/home`, нажать «התחל תפילה».
    // Вне окна молитвы кнопка неактивна (норма): хелпер проверяет disabled + «מתחילה ב-…» и открывает
    // /prayer/<תפילה>_<נוסח из карточки> — нусах по-прежнему берётся из профиля через карточку /home.
    await page.goto('/home');
    await startNearestPrayer(page);
    await expect(page).toHaveURL(/\/prayer\//);
    await expect(page.getByRole('heading', { level: 1 })).toContainText('(אשכנזי)');
  });
});
